    <BaseToolbar.Link
      className={cn(
        'inline-flex h-8 items-center rounded-full px-3 text-[13px] font-semibold text-[#4A4FB8] transition-colors duration-150 ease-[cubic-bezier(0.2,0,0,1)] hover:bg-[#E4E6FD]',
