import * as React from 'react'
import {
  PolarAngleAxis,
  RadialBar,
  RadialBarChart as RechartsRadialBarChart,
} from 'recharts'
import { cn } from 'cn'
import { DATAVIZ_PALETTES, HUE_PALETTES, type Hue, type TileTone } from '@/lib/tokens'
import {
  CHART_ANIMATION_DURATION,
  CHART_ANIMATION_EASING,
  ChartContainer,
  ChartLegend,
  ChartTooltip,
  ChartTooltipContent,
  useChartTheme,
  type ChartConfig,
} from '@/components/ui/chart'

export interface RadialChartItem {
  name: string
  value: number
  color?: string
  hue?: Hue
}

export interface RadialChartProps {
  data: RadialChartItem[]
  max?: number
  tone?: TileTone
  height?: number | string
  startAngle?: number
  endAngle?: number
  innerRadius?: number | string
  outerRadius?: number | string
  barSize?: number
  centerValue?: React.ReactNode
  centerLabel?: React.ReactNode
  showTooltip?: boolean
  showLegend?: boolean
  valueFormatter?: (value: number | string, name?: string) => React.ReactNode
  animate?: boolean
  className?: string
}

export function RadialChart({
  data,
  max = 100,
  tone,
  height = 220,
  startAngle = 90,
  endAngle = -270,
  innerRadius = '36%',
  outerRadius = '92%',
  barSize = 12,
  centerValue,
  centerLabel,
  showTooltip = true,
  showLegend = false,
  valueFormatter,
  animate = true,
  className,
}: RadialChartProps) {
  const theme = useChartTheme(tone)

  const resolvedData = React.useMemo(
    () =>
      data.map((item, idx) => ({
        ...item,
        fill:
          item.color ??
          (item.hue ? HUE_PALETTES[item.hue][500] : undefined) ??
          DATAVIZ_PALETTES.categorical[idx % DATAVIZ_PALETTES.categorical.length],
      })),
    [data],
  )

  const config = React.useMemo<ChartConfig>(() => {
    const out: ChartConfig = {}
    resolvedData.forEach((d) => {
      out[d.name] = { label: d.name, color: d.fill }
    })
    return out
  }, [resolvedData])

  return (
    <div className={cn('flex w-full min-w-0 flex-col gap-3', className)}>
      <div className="relative w-full" style={{ height }}>
        <ChartContainer config={config} tone={tone} height="100%">
          <RechartsRadialBarChart
            data={resolvedData}
            cx="50%"
            cy="50%"
            innerRadius={innerRadius}
            outerRadius={outerRadius}
            barSize={barSize}
            startAngle={startAngle}
            endAngle={endAngle}
          >
            <PolarAngleAxis type="number" domain={[0, max]} tick={false} />
            {showTooltip && (
              <ChartTooltip
                content={(tooltipProps) => (
                  <ChartTooltipContent
                    active={tooltipProps.active}
                    payload={tooltipProps.payload}
                    label={tooltipProps.label}
                    hideLabel
                    valueFormatter={valueFormatter}
                  />
                )}
              />
            )}
            <RadialBar
              dataKey="value"
              cornerRadius={999}
              background={{ fill: theme.tile.track }}
              isAnimationActive={animate}
              animationDuration={CHART_ANIMATION_DURATION}
              animationEasing={CHART_ANIMATION_EASING}
            />
          </RechartsRadialBarChart>
        </ChartContainer>

        {(centerValue !== undefined || centerLabel !== undefined) && (
          <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center">
            {centerValue !== undefined && (
              <span
                className="font-glaze-display text-[24px] leading-7 font-extrabold"
                style={{ color: theme.tile.ink }}
              >
                {centerValue}
              </span>
            )}
            {centerLabel !== undefined && (
              <span className="mt-0.5 text-[11px] font-medium" style={{ color: theme.axisColor }}>
                {centerLabel}
              </span>
            )}
          </div>
        )}
      </div>

      {showLegend && (
        <ChartLegend
          tone={tone}
          align="center"
          items={resolvedData.map((d) => ({
            key: d.name,
            label: d.name,
            color: d.fill,
          }))}
        />
      )}
    </div>
  )
}

export interface GaugeChartProps {
  value: number
  max?: number
  label?: string
  valueText?: React.ReactNode
  unit?: string
  subLabel?: React.ReactNode
  variant?: 'semicircle' | 'ring'
  color?: string
  hue?: Hue
  trackColor?: string
  tone?: TileTone
  width?: number
  height?: number
  barSize?: number
  showTooltip?: boolean
  animate?: boolean
  className?: string
}

export function GaugeChart({
  value,
  max = 100,
  label = '数值',
  valueText,
  unit,
  subLabel,
  variant = 'semicircle',
  color,
  hue,
  trackColor,
  tone,
  width,
  height,
  barSize,
  showTooltip = false,
  animate = true,
  className,
}: GaugeChartProps) {
  const theme = useChartTheme(tone)
  const clamped = Math.max(0, Math.min(max, value))
  const accent = color ?? (hue ? HUE_PALETTES[hue][500] : theme.tile.accent)
  const track = trackColor ?? theme.tile.track
  const isSemi = variant === 'semicircle'

  const w = width ?? (isSemi ? 148 : 96)
  const h = height ?? (isSemi ? 86 : 96)
  const thickness = barSize ?? (isSemi ? 12 : 10)

  const data = React.useMemo(
    () => [{ name: label, value: clamped, fill: accent }],
    [label, clamped, accent],
  )

  const config = React.useMemo<ChartConfig>(
    () => ({ [label]: { label, color: accent, unit } }),
    [label, accent, unit],
  )

  return (
    <div
      role="img"
      aria-label={`${label} ${valueText ?? `${clamped}${unit ?? '%'}`}`}
      className={cn('relative inline-flex shrink-0 items-center justify-center', className)}
      style={{ width: w, height: h }}
    >
      <ChartContainer config={config} tone={tone} height="100%">
        <RechartsRadialBarChart
          data={data}
          cx="50%"
          cy={isSemi ? '88%' : '50%'}
          innerRadius={isSemi ? '128%' : '76%'}
          outerRadius={isSemi ? '160%' : '100%'}
          barSize={thickness}
          startAngle={isSemi ? 180 : 90}
          endAngle={isSemi ? 0 : -270}
          margin={{ top: 0, right: 0, bottom: 0, left: 0 }}
        >
          <PolarAngleAxis type="number" domain={[0, max]} tick={false} />
          {showTooltip && (
            <ChartTooltip
              content={(tooltipProps) => (
                <ChartTooltipContent
                  active={tooltipProps.active}
                  payload={tooltipProps.payload}
                  label={tooltipProps.label}
                  surface="ink"
                  compact
                  hideLabel
                />
              )}
            />
          )}
          <RadialBar
            dataKey="value"
            cornerRadius={999}
            background={{ fill: track }}
            isAnimationActive={animate}
            animationDuration={CHART_ANIMATION_DURATION}
            animationEasing={CHART_ANIMATION_EASING}
          />
        </RechartsRadialBarChart>
      </ChartContainer>

      <div
        className={cn(
          'pointer-events-none absolute inset-x-0 flex flex-col items-center justify-center text-center',
          isSemi ? 'bottom-0' : 'inset-y-0',
        )}
      >
        <span
          className="inline-flex items-baseline gap-0.5 whitespace-nowrap font-glaze-display font-extrabold"
          style={{
            color: theme.tile.ink,
            fontSize: isSemi ? 24 : 19,
            lineHeight: isSemi ? '26px' : '22px',
          }}
        >
          <span>{valueText ?? `${Math.round((clamped / max) * 100)}%`}</span>
          {unit && (
            <span className="text-[11px] font-semibold" style={{ color: theme.axisColor }}>
              {unit}
            </span>
          )}
        </span>
        {subLabel && (
          <span className="mt-0.5 text-[11px] font-medium" style={{ color: theme.axisColor }}>
            {subLabel}
          </span>
        )}
      </div>
    </div>
  )
}

scatter-chart.sourceCode:
import * as React from 'react'
import {
  CartesianGrid,
  Scatter,
  ScatterChart as RechartsScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from 'recharts'
import { cn } from 'cn'
import type { Hue, TileTone } from '@/lib/tokens'
import {
  CHART_ANIMATION_DURATION,
  CHART_ANIMATION_EASING,
  ChartContainer,
  ChartLegend,
  ChartTooltip,
  ChartTooltipContent,
  resolveSeriesColor,
  useChartTheme,
  type ChartConfig,
} from '@/components/ui/chart'

export interface ScatterSeries {
  id?: string
  name: string
  data: readonly object[]
  color?: string
  hue?: Hue
}

export interface ScatterChartProps {
  series: ScatterSeries[]
  xKey: string
  yKey: string
  zKey?: string
  xLabel?: string
  yLabel?: string
  xUnit?: string
  yUnit?: string
  zRange?: [number, number]
  tone?: TileTone
  height?: number | string
  showGrid?: boolean
  showXAxis?: boolean
  showYAxis?: boolean
  showTooltip?: boolean
  showLegend?: boolean
  interactiveLegend?: boolean
  xTickFormatter?: (value: unknown) => string
  yTickFormatter?: (value: unknown) => string
  yAxisWidth?: number | 'auto'
  animate?: boolean
  className?: string
}

export function ScatterChart({
  series,
  xKey,
  yKey,
  zKey,
  xLabel,
  yLabel,
  xUnit,
  yUnit,
  zRange = [48, 280],
  tone,
  height = 220,
  showGrid = true,
  showXAxis = true,
  showYAxis = true,
  showTooltip = true,
  showLegend = true,
  interactiveLegend = true,
  xTickFormatter,
  yTickFormatter,
  yAxisWidth = 'auto',
  animate = true,
  className,
}: ScatterChartProps) {
  const theme = useChartTheme(tone)
  const [hiddenKeys, setHiddenKeys] = React.useState<Set<string>>(() => new Set())

  const resolvedSeries = React.useMemo(
    () =>
      series.map((s, idx) => {
        const key = s.id ?? s.name
        return {
          ...s,
          key,
          resolvedColor: resolveSeriesColor(key, idx, undefined, s.color, s.hue),
        }
      }),
    [series],
  )

  const config = React.useMemo<ChartConfig>(() => {
    const out: ChartConfig = {
      [xKey]: { label: xLabel ?? xKey, unit: xUnit },
      [yKey]: { label: yLabel ?? yKey, unit: yUnit },
    }
    resolvedSeries.forEach((s) => {
      out[s.key] = { label: s.name, color: s.resolvedColor }
    })
    return out
  }, [resolvedSeries, xKey, yKey, xLabel, yLabel, xUnit, yUnit])

  const toggleKey = React.useCallback((key: string) => {
    setHiddenKeys((prev) => {
      const next = new Set(prev)
      if (next.has(key)) next.delete(key)
      else next.add(key)
      return next
    })
  }, [])

  return (
    <div className={cn('flex w-full min-w-0 flex-col gap-2.5', className)}>
      {showLegend && (
        <ChartLegend
          tone={tone}
          items={resolvedSeries.map((s) => ({
            key: s.key,
            label: s.name,
            color: s.resolvedColor,
          }))}
          hiddenKeys={interactiveLegend ? hiddenKeys : undefined}
          onToggleKey={interactiveLegend ? toggleKey : undefined}
        />
      )}
      <ChartContainer config={config} tone={tone} height={height}>
        <RechartsScatterChart margin={{ top: 10, right: 16, bottom: 4, left: 6 }}>
          {showGrid && (
            <CartesianGrid stroke={theme.gridColor} strokeDasharray="3 4" />
          )}
          {showXAxis && (
            <XAxis
              type="number"
              dataKey={xKey}
              name={xLabel ?? xKey}
              unit={xUnit}
              axisLine={false}
              tickLine={false}
              tickMargin={8}
              tick={{ fill: theme.axisColor }}
              tickFormatter={xTickFormatter ? (v) => xTickFormatter(v) : undefined}
            />
          )}
          {showYAxis && (
            <YAxis
              type="number"
              dataKey={yKey}
              name={yLabel ?? yKey}
              unit={yUnit}
              width={yAxisWidth}
              axisLine={false}
              tickLine={false}
              tickMargin={6}
              tick={{ fill: theme.axisColor }}
              tickFormatter={yTickFormatter ? (v) => yTickFormatter(v) : undefined}
            />
          )}
          {zKey && <ZAxis type="number" dataKey={zKey} range={zRange} />}
          {showTooltip && (
            <ChartTooltip
              cursor={{ strokeDasharray: '3 3', stroke: theme.cursorStroke }}
              content={(tooltipProps) => (
                <ChartTooltipContent
                  active={tooltipProps.active}
                  payload={tooltipProps.payload}
                  label={tooltipProps.label}
                  hideLabel
                />
              )}
            />
          )}
          {resolvedSeries.map((s) => {
            if (hiddenKeys.has(s.key)) return null
            return (
              <Scatter
                key={s.key}
                name={s.name}
                data={s.data}
                fill={s.resolvedColor}
                fillOpacity={0.78}
                stroke={s.resolvedColor}
                strokeWidth={1.5}
                isAnimationActive={animate}
                animationDuration={CHART_ANIMATION_DURATION}
                animationEasing={CHART_ANIMATION_EASING}
              />
            )
          })}
        </RechartsScatterChart>
      </ChartContainer>
    </div>
  )
}

composed-chart.sourceCode:
import * as React from 'react'
import {
  Area,
  Bar,
  CartesianGrid,
  ComposedChart as RechartsComposedChart,
  Line,
  XAxis,
  YAxis,
} from 'recharts'
import { cn } from 'cn'
import type { Hue, TileTone } from '@/lib/tokens'
import {
  CHART_ANIMATION_DURATION,
  CHART_ANIMATION_EASING,
  ChartContainer,
  ChartLegend,
  ChartTooltip,
  ChartTooltipContent,
  resolveSeriesColor,
  useChartTheme,
  type ChartConfig,
} from '@/components/ui/chart'

export interface ComposedSeries {
  type: 'bar' | 'line' | 'area'
  dataKey: string
  label?: string
  color?: string
  hue?: Hue
  unit?: string
  yAxisId?: 'left' | 'right'
  stackId?: string
  dashed?: boolean
  barSize?: number
  strokeWidth?: number
  fillOpacity?: number
}

export interface ComposedChartProps {
  data: readonly object[]
  xKey: string
  series: ComposedSeries[]
  config?: ChartConfig
  tone?: TileTone
  height?: number | string
  curve?: 'monotone' | 'natural' | 'linear'
  showGrid?: boolean
  showXAxis?: boolean
  showYAxis?: boolean
  showTooltip?: boolean
  showLegend?: boolean
  interactiveLegend?: boolean
  xTickFormatter?: (value: unknown) => string
  leftYTickFormatter?: (value: unknown) => string
  rightYTickFormatter?: (value: unknown) => string
  valueFormatter?: (value: number | string, name?: string) => React.ReactNode
  leftYAxisWidth?: number | 'auto'
  rightYAxisWidth?: number | 'auto'
  animate?: boolean
  className?: string
}

export function ComposedChart({
  data,
  xKey,
  series,
  config,
  tone,
  height = 240,
  curve = 'monotone',
  showGrid = true,
  showXAxis = true,
  showYAxis = true,
  showTooltip = true,
  showLegend = true,
  interactiveLegend = true,
  xTickFormatter,
  leftYTickFormatter,
  rightYTickFormatter,
  valueFormatter,
  leftYAxisWidth = 'auto',
  rightYAxisWidth = 'auto',
  animate = true,
  className,
}: ComposedChartProps) {
  const uid = React.useId().replace(/:/g, '')
  const theme = useChartTheme(tone)
  const [hiddenKeys, setHiddenKeys] = React.useState<Set<string>>(() => new Set())

  const hasRightAxis = series.some((s) => s.yAxisId === 'right')

  const resolvedSeries = React.useMemo(
    () =>
      series.map((s, idx) => ({
        ...s,
        resolvedColor: resolveSeriesColor(s.dataKey, idx, config, s.color, s.hue),
        resolvedLabel: s.label ?? config?.[s.dataKey]?.label ?? s.dataKey,
      })),
    [series, config],
  )

  const mergedConfig = React.useMemo<ChartConfig>(() => {
    const out: ChartConfig = { ...config }
    resolvedSeries.forEach((s) => {
      out[s.dataKey] = {
        ...out[s.dataKey],
        label: s.resolvedLabel,
        color: s.resolvedColor,
        unit: s.unit ?? out[s.dataKey]?.unit,
      }
    })
    return out
  }, [config, resolvedSeries])

  const toggleKey = React.useCallback((key: string) => {
    setHiddenKeys((prev) => {
      const next = new Set(prev)
      if (next.has(key)) next.delete(key)
      else next.add(key)
      return next
    })
  }, [])

  return (
    <div className={cn('flex w-full min-w-0 flex-col gap-2.5', className)}>
      {showLegend && (
        <ChartLegend
          tone={tone}
          items={resolvedSeries.map((s) => ({
            key: s.dataKey,
            label: s.resolvedLabel,
            color: s.resolvedColor,
            dashed: s.dashed,
          }))}
          hiddenKeys={interactiveLegend ? hiddenKeys : undefined}
          onToggleKey={interactiveLegend ? toggleKey : undefined}
        />
      )}
      <ChartContainer config={mergedConfig} tone={tone} height={height}>
        <RechartsComposedChart
          data={data}
          margin={{ top: 8, right: hasRightAxis ? 8 : 10, bottom: 0, left: 6 }}
        >
          <defs>
            {resolvedSeries
              .filter((s) => s.type === 'area')
              .map((s) => (
                <linearGradient
                  key={s.dataKey}
                  id={`glaze-composed-${uid}-${s.dataKey}`}
                  x1="0"
                  y1="0"
                  x2="0"
                  y2="1"
                >
                  <stop offset="0%" stopColor={s.resolvedColor} stopOpacity={s.fillOpacity ?? 0.24} />
                  <stop offset="96%" stopColor={s.resolvedColor} stopOpacity={0.01} />
                </linearGradient>
              ))}
          </defs>

          {showGrid && (
            <CartesianGrid
              vertical={false}
              stroke={theme.gridColor}
              strokeDasharray="3 4"
            />
          )}

          {showXAxis && (
            <XAxis
              dataKey={xKey}
              axisLine={false}
              tickLine={false}
              tickMargin={8}
              tick={{ fill: theme.axisColor }}
              tickFormatter={xTickFormatter ? (v) => xTickFormatter(v) : undefined}
            />
          )}

          {showYAxis && (
            <YAxis
              yAxisId="left"
              width={leftYAxisWidth}
              axisLine={false}
              tickLine={false}
              tickMargin={6}
              tick={{ fill: theme.axisColor }}
              tickFormatter={leftYTickFormatter ? (v) => leftYTickFormatter(v) : undefined}
            />
          )}

          {showYAxis && hasRightAxis && (
            <YAxis
              yAxisId="right"
              orientation="right"
              width={rightYAxisWidth}
              axisLine={false}
              tickLine={false}
              tickMargin={6}
              tick={{ fill: theme.axisColor }}
              tickFormatter={rightYTickFormatter ? (v) => rightYTickFormatter(v) : undefined}
            />
          )}

          {showTooltip && (
            <ChartTooltip
              cursor={{ fill: theme.cursorFill, radius: 8 }}
              content={(tooltipProps) => (
                <ChartTooltipContent
                  active={tooltipProps.active}
                  payload={tooltipProps.payload}
                  label={tooltipProps.label}
                  valueFormatter={valueFormatter}
                />
              )}
            />
          )}

          {resolvedSeries.map((s) => {
            if (hiddenKeys.has(s.dataKey)) return null
            const yAxisId = s.yAxisId ?? 'left'
            if (s.type === 'bar') {
              return (
                <Bar
                  key={s.dataKey}
                  yAxisId={yAxisId}
                  dataKey={s.dataKey}
                  name={String(s.resolvedLabel)}
                  stackId={s.stackId}
                  fill={s.resolvedColor}
                  barSize={s.barSize ?? 20}
                  radius={[7, 7, 3, 3]}
                  isAnimationActive={animate}
                  animationDuration={CHART_ANIMATION_DURATION}
                  animationEasing={CHART_ANIMATION_EASING}
                />
              )
            }
            if (s.type === 'area') {
              return (
                <Area
                  key={s.dataKey}
                  yAxisId={yAxisId}
                  type={curve}
                  dataKey={s.dataKey}
                  name={String(s.resolvedLabel)}
                  stackId={s.stackId}
                  stroke={s.resolvedColor}
                  strokeWidth={s.strokeWidth ?? 2.25}
                  strokeDasharray={s.dashed ? '5 4' : undefined}
                  fill={`url(#glaze-composed-${uid}-${s.dataKey})`}
                  dot={false}
                  activeDot={{ r: 4, fill: s.resolvedColor, stroke: theme.tile.bg, strokeWidth: 2 }}
                  isAnimationActive={animate}
                  animationDuration={CHART_ANIMATION_DURATION}
                  animationEasing={CHART_ANIMATION_EASING}
                />
              )
            }
            return (
              <Line
                key={s.dataKey}
                yAxisId={yAxisId}
                type={curve}
                dataKey={s.dataKey}
                name={String(s.resolvedLabel)}
                stroke={s.resolvedColor}
                strokeWidth={s.strokeWidth ?? 2.5}
                strokeDasharray={s.dashed ? '5 4' : undefined}
                strokeLinecap="round"
                dot={{ r: 3.5, fill: theme.tile.bg, stroke: s.resolvedColor, strokeWidth: 2 }}
                activeDot={{ r: 4.5, fill: s.resolvedColor, stroke: theme.tile.bg, strokeWidth: 2 }}
                isAnimationActive={animate}
                animationDuration={CHART_ANIMATION_DURATION}
                animationEasing={CHART_ANIMATION_EASING}
              />
            )
          })}
        </RechartsComposedChart>
      </ChartContainer>
    </div>
  )
}

spark-chart.sourceCode:
import * as React from 'react'
import {
  Area,
  AreaChart as RechartsAreaChart,
  Bar,
  BarChart as RechartsBarChart,
  Line,
  LineChart as RechartsLineChart,
  Rectangle,
  type BarShapeProps,
} from 'recharts'
import { HUE_PALETTES, type Hue, type TileTone } from '@/lib/tokens'
import {
  CHART_ANIMATION_DURATION,
  CHART_ANIMATION_EASING,
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  useChartTheme,
  type ChartConfig,
} from '@/components/ui/chart'

export type SparkChartDataItem = number | { label?: string; value: number }

export interface SparkChartProps {
  data: SparkChartDataItem[]
  variant?: 'line' | 'area' | 'bar'
  color?: string
  hue?: Hue
  mutedColor?: string
  highlightLast?: boolean
  curve?: 'monotone' | 'natural' | 'linear'
  strokeWidth?: number
  height?: number | string
  label?: string
  unit?: string
  showTooltip?: boolean
  valueFormatter?: (value: number | string) => React.ReactNode
  tone?: TileTone
  animate?: boolean
  className?: string
}

export function SparkChart({
  data,
  variant = 'line',
  color,
  hue,
  mutedColor,
  highlightLast = true,
  curve = 'monotone',
  strokeWidth = 2.4,
  height = 36,
  label = '数值',
  unit,
  showTooltip = true,
  valueFormatter,
  tone,
  animate = true,
  className,
}: SparkChartProps) {
  const uid = React.useId().replace(/:/g, '')
  const theme = useChartTheme(tone)
  const accent = color ?? (hue ? HUE_PALETTES[hue][500] : theme.tile.accent)
  const muted = mutedColor ?? (hue ? HUE_PALETTES[hue][100] : theme.tile.mutedBar)

  const normalized = React.useMemo(
    () =>
      data.map((d, idx) =>
        typeof d === 'number'
          ? { label: `#${idx + 1}`, value: d }
          : { label: d.label ?? `#${idx + 1}`, value: d.value },
      ),
    [data],
  )

  const config = React.useMemo<ChartConfig>(
    () => ({ value: { label, color: accent, unit } }),
    [label, accent, unit],
  )

  const tooltip = showTooltip ? (
    <ChartTooltip
      allowEscapeViewBox={{ x: false, y: true }}
      offset={8}
      cursor={
        variant === 'bar'
          ? { fill: theme.cursorFill, radius: 4 }
          : { stroke: theme.cursorStroke, strokeWidth: 1, strokeDasharray: '3 3' }
      }
      content={(tooltipProps) => (
        <ChartTooltipContent
          active={tooltipProps.active}
          payload={tooltipProps.payload}
          label={tooltipProps.label}
          surface="ink"
          compact
          hideLabel={normalized.every((d, i) => d.label === `#${i + 1}`)}
          valueFormatter={valueFormatter ? (v) => valueFormatter(v) : undefined}
        />
      )}
    />
  ) : null

  if (variant === 'bar') {
    const lastIdx = normalized.length - 1
    return (
      <ChartContainer config={config} tone={tone} height={height} className={className}>
        <RechartsBarChart
          data={normalized}
          barCategoryGap="18%"
          margin={{ top: 2, right: 0, bottom: 0, left: 0 }}
        >
          {tooltip}
          <Bar
            dataKey="value"
            name={label}
            fill={accent}
            radius={[3, 3, 2, 2]}
            shape={(barProps: BarShapeProps) => (
              <Rectangle
                {...barProps}
                fill={!highlightLast || barProps.index === lastIdx ? accent : muted}
              />
            )}
            isAnimationActive={animate}
            animationDuration={CHART_ANIMATION_DURATION}
            animationEasing={CHART_ANIMATION_EASING}
          />
        </RechartsBarChart>
      </ChartContainer>
    )
  }

  if (variant === 'area') {
    return (
      <ChartContainer config={config} tone={tone} height={height} className={className}>
        <RechartsAreaChart
          data={normalized}
          margin={{ top: 3, right: 2, bottom: 2, left: 2 }}
        >
          <defs>
            <linearGradient id={`glaze-spark-${uid}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={accent} stopOpacity={0.26} />
              <stop offset="100%" stopColor={accent} stopOpacity={0.02} />
            </linearGradient>
          </defs>
          {tooltip}
          <Area
            type={curve}
            dataKey="value"
            name={label}
            stroke={accent}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            fill={`url(#glaze-spark-${uid})`}
            dot={false}
            activeDot={{ r: 3.5, fill: accent, stroke: theme.tile.bg, strokeWidth: 1.5 }}
            isAnimationActive={animate}
            animationDuration={CHART_ANIMATION_DURATION}
            animationEasing={CHART_ANIMATION_EASING}
          />
        </RechartsAreaChart>
      </ChartContainer>
    )
  }

  return (
    <ChartContainer config={config} tone={tone} height={height} className={className}>
      <RechartsLineChart
        data={normalized}
        margin={{ top: 3, right: 2, bottom: 3, left: 2 }}
      >
        {tooltip}
        <Line
          type={curve}
          dataKey="value"
          name={label}
          stroke={accent}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          dot={false}
          activeDot={{ r: 3.5, fill: accent, stroke: theme.tile.bg, strokeWidth: 1.5 }}
          isAnimationActive={animate}
          animationDuration={CHART_ANIMATION_DURATION}
          animationEasing={CHART_ANIMATION_EASING}
        />
      </RechartsLineChart>
    </ChartContainer>
  )
}

