import * as React from 'react'
import { Check, Code, Copy, TerminalWindow, TextAlignLeft } from '@phosphor-icons/react'
import { cn } from 'cn'
import { StatusPill } from '@/components/ui/status-pill'
import { PRESS_CLASS } from '@/lib/motion'

export interface AiCodeBlockProps extends React.HTMLAttributes<HTMLDivElement> {
  code: string
  language?: string
  filename?: string
  showLineNumbers?: boolean
  /** Highlight +/- unified diff lines */
  diff?: boolean
  /** Surface variant: light (inside white/pastel card) or dark (ink terminal style) */
  variant?: 'light' | 'dark'
  maxHeight?: number
}

export function AiCodeBlock({
  code,
  language = 'tsx',
  filename,
  showLineNumbers = true,
  diff = false,
  variant = 'light',
  maxHeight = 360,
  className,
  ...props
}: AiCodeBlockProps) {
  const [copied, setCopied] = React.useState(false)
  const [wrap, setWrap] = React.useState(false)
  const lines = React.useMemo(() => code.replace(/\n$/, '').split('\n'), [code])

  const handleCopy = () => {
    navigator.clipboard?.writeText(code).catch(() => {})
    setCopied(true)
    window.setTimeout(() => setCopied(false), 1600)
  }

  const isDark = variant === 'dark'

  return (
    <div
      data-variant={variant}
      className={cn(
        'w-full overflow-hidden rounded-inner',
        isDark ? 'bg-[#1B1F27] text-[#F2F4F8]' : 'bg-[#F6F7F9] text-[#1B1F27]',
        className,
      )}
      {...props}
    >
      <div
        className={cn(
          'flex items-center justify-between gap-2 px-3.5 py-2',
          isDark ? 'border-b border-white/10' : 'border-b border-[#E8EBF0]',
        )}
      >
        <div className="flex min-w-0 items-center gap-2">
          <Code size={14} weight="bold" className={isDark ? 'text-[#B5BAF6]' : 'text-[#4A4FB8]'} />
          <span
            className={cn(
              'truncate font-glaze-mono text-[12px] font-semibold',
              isDark ? 'text-[#C5CAD3]' : 'text-[#5B6170]',
            )}
          >
            {filename ?? language}
          </span>
          {filename && (
            <span
              className={cn(
                'rounded-full px-2 py-0.5 font-glaze-mono text-[10px] font-bold uppercase',
                isDark ? 'bg-white/10 text-[#B5BAF6]' : 'bg-white text-[#6B7280]',
              )}
            >
              {language}
            </span>
          )}
        </div>

        <div className="flex shrink-0 items-center gap-1">
          <button
            type="button"
            onClick={() => setWrap((w) => !w)}
            aria-label="切换自动换行"
            className={cn(
              'inline-flex h-7 cursor-pointer items-center gap-1 rounded-full px-2 text-[11px] font-semibold outline-none',
              PRESS_CLASS,
              isDark
                ? wrap
                  ? 'bg-white/20 text-white'
                  : 'text-[#C5CAD3] hover:bg-white/10'
                : wrap
                  ? 'bg-[#E4E6FD] text-[#262B7A]'
                  : 'text-[#6B7280] hover:bg-white',
            )}
          >
            <TextAlignLeft size={12} weight="bold" />
            <span className="hidden sm:inline">{wrap ? '不换行' : '换行'}</span>
          </button>
          <button
            type="button"
            onClick={handleCopy}
            className={cn(
              'inline-flex h-7 cursor-pointer items-center gap-1 rounded-full px-2.5 text-[11px] font-semibold outline-none',
              PRESS_CLASS,
              isDark
                ? 'bg-white/10 text-white hover:bg-white/20'
                : 'bg-white text-[#1B1F27] hover:bg-[#E8EBF0]',
            )}
          >
            {copied ? <Check size={12} weight="bold" /> : <Copy size={12} />}
            <span>{copied ? '已复制' : '复制'}</span>
          </button>
        </div>
      </div>

      <div
        className="overflow-auto px-3 py-3 font-glaze-mono text-[12.5px] leading-[1.6]"
        style={{ maxHeight }}
      >
        <div className={cn('min-w-max', wrap && 'min-w-0')}>
          {lines.map((line, i) => {
            const isAdd = diff && line.startsWith('+') && !line.startsWith('+++')
            const isDel = diff && line.startsWith('-') && !line.startsWith('---')
            return (
              <div
                key={i}
                className={cn(
                  'flex rounded-[6px] px-1.5',
                  wrap ? 'whitespace-pre-wrap break-all' : 'whitespace-pre',
                  isAdd && (isDark ? 'bg-[#49A851]/20 text-[#B2DE9F]' : 'bg-[#E2F5DA] text-[#173F12]'),
                  isDel && (isDark ? 'bg-[#E5603B]/20 text-[#F7B39C]' : 'bg-[#FDE5DC] text-[#A6360F]'),
                )}
              >
                {showLineNumbers && (
                  <span
                    className={cn(
                      'mr-3 inline-block w-6 shrink-0 text-right text-[11px] select-none',
                      isDark ? 'text-white/30' : 'text-[#8A90A0]',
                    )}
                  >
                    {i + 1}
                  </span>
                )}
                <span className="flex-1">{line || ' '}</span>
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}

export interface AiTerminalProps extends React.HTMLAttributes<HTMLDivElement> {
  command?: string
  output: string
  status?: 'running' | 'success' | 'error'
  exitCode?: number
  cwd?: string
  maxHeight?: number
}

export function AiTerminal({
  command,
  output,
  status = 'success',
  exitCode,
  cwd = '~/workspace/glaze-ui',
  maxHeight = 260,
  className,
  ...props
}: AiTerminalProps) {
  const [copied, setCopied] = React.useState(false)

  const handleCopy = () => {
    const text = command ? `$ ${command}\n${output}` : output
    navigator.clipboard?.writeText(text).catch(() => {})
    setCopied(true)
    window.setTimeout(() => setCopied(false), 1600)
  }

  return (
    <div
      className={cn('w-full overflow-hidden rounded-inner bg-[#1B1F27] text-[#F2F4F8]', className)}
      {...props}
    >
      <div className="flex items-center justify-between gap-2 border-b border-white/10 px-3.5 py-2">
        <div className="flex min-w-0 items-center gap-2">
          <TerminalWindow size={14} weight="duotone" className="shrink-0 text-[#93DAD3]" />
          <span className="truncate font-glaze-mono text-[11.5px] font-semibold text-[#C5CAD3]">
            {cwd}
          </span>
        </div>
        <div className="flex shrink-0 items-center gap-2">
          {status === 'running' && <StatusPill status="info" label="运行中" size="sm" />}
          {status === 'success' && (
            <StatusPill
              status="normal"
              label={exitCode !== undefined ? `exit ${exitCode}` : '完成'}
              size="sm"
            />
          )}
          {status === 'error' && (
            <StatusPill
              status="error"
              label={exitCode !== undefined ? `exit ${exitCode}` : '失败'}
              size="sm"
            />
          )}
          <button
            type="button"
            onClick={handleCopy}
            className={cn(
              'inline-flex h-6 cursor-pointer items-center gap-1 rounded-full bg-white/10 px-2 text-[11px] font-semibold text-white hover:bg-white/20',
              PRESS_CLASS,
            )}
          >
            {copied ? <Check size={11} weight="bold" /> : <Copy size={11} />}
            <span>{copied ? '已复制' : '复制'}</span>
          </button>
        </div>
      </div>

      <div
        className="overflow-auto px-3.5 py-3 font-glaze-mono text-[12px] leading-relaxed"
        style={{ maxHeight }}
      >
        {command && (
          <div className="mb-1.5 flex items-baseline gap-2 text-[#B5BAF6]">
            <span className="select-none text-[#93DAD3]">$</span>
            <span className="font-semibold text-white">{command}</span>
          </div>
        )}
        <pre className="m-0 whitespace-pre-wrap text-[#C5CAD3]">
          {output}
          {status === 'running' && (
            <span
              aria-hidden="true"
              className="animate-glaze-caret ml-1 inline-block h-3.5 w-1.5 bg-[#93DAD3] align-middle"
            />
          )}
        </pre>
      </div>
    </div>
  )
}

ai-suggestions.sourceCode:
import * as React from 'react'
import { CheckCircle, Circle, CircleNotch, Sparkle } from '@phosphor-icons/react'
import { cn } from 'cn'
import { HUE_PALETTES, SEMANTIC_TOKENS, type Hue } from '@/lib/tokens'
import { PRESS_CLASS } from '@/lib/motion'

export interface AiSuggestionsProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Wrap chips across lines or scroll horizontally */
  layout?: 'wrap' | 'scroll'
}

export function AiSuggestions({
  layout = 'wrap',
  className,
  ...props
}: AiSuggestionsProps) {
  return (
    <div
      className={cn(
        'flex items-center gap-2',
        layout === 'wrap' ? 'flex-wrap' : 'flex-nowrap overflow-x-auto pb-1',
        className,
      )}
      {...props}
    />
  )
}

export interface AiSuggestionProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'onClick' | 'onSelect'> {
  suggestion: string
  onSelect?: (suggestion: string) => void
  icon?: React.ReactNode
  hue?: Hue
  /** Soft neutral or tinted pastel chip */
  variant?: 'neutral' | 'tinted'
}

export function AiSuggestion({
  suggestion,
  onSelect,
  icon,
  hue = 'periwinkle',
  variant = 'neutral',
  className,
  children,
  ...props
}: AiSuggestionProps) {
  const palette = HUE_PALETTES[hue]
  return (
    <button
      type="button"
      onClick={() => onSelect?.(suggestion)}
      className={cn(
        'inline-flex h-9 shrink-0 cursor-pointer items-center gap-1.5 rounded-full px-3.5 text-[12.5px] font-semibold outline-none',
        PRESS_CLASS,
        variant === 'neutral' &&
          'bg-[#F6F7F9] text-[#1B1F27] hover:bg-[#E8EBF0]',
        variant === 'tinted' && 'hover:brightness-[0.96]',
        className,
      )}
      style={
        variant === 'tinted'
          ? { backgroundColor: palette[100], color: palette[700] }
          : undefined
      }
      {...props}
    >
      <span
        className="shrink-0"
        style={{ color: variant === 'tinted' ? palette[700] : palette[500] }}
      >
        {icon ?? <Sparkle size={13} weight="duotone" />}
      </span>
      <span>{children ?? suggestion}</span>
    </button>
  )
}

export interface AiQueueTask {
  id: string
  title: string
  meta?: string
  status: 'pending' | 'running' | 'completed'
}

export interface AiQueueProps extends React.HTMLAttributes<HTMLDivElement> {
  items: AiQueueTask[]
  title?: string
  showCompleted?: boolean
}

export function AiQueue({
  items,
  title = 'Agent 任务队列',
  showCompleted = true,
  className,
  ...props
}: AiQueueProps) {
  const remaining = items.filter((i) => i.status !== 'completed')
  const completed = items.filter((i) => i.status === 'completed')

  return (
    <div
      className={cn('flex w-full flex-col gap-3 rounded-inner bg-[#F6F7F9] p-3.5', className)}
      {...props}
    >
      <div className="flex items-center justify-between gap-2">
        <span className="font-glaze-display text-[13.5px] font-extrabold text-[#1B1F27]">
          {title}
        </span>
        <span className="rounded-full bg-white px-2.5 py-0.5 font-glaze-mono text-[11px] font-bold text-[#4A4FB8]">
          {completed.length}/{items.length}
        </span>
      </div>

      {remaining.length > 0 && (
        <div className="flex flex-col gap-1">
          <span className="px-1 text-[10.5px] font-bold tracking-[0.04em] text-[#8A90A0] uppercase">
            待执行 ({remaining.length})
          </span>
          {remaining.map((item) => (
            <div
              key={item.id}
              className={cn(
                'flex items-center justify-between gap-2 rounded-[10px] px-2.5 py-1.5 text-[12.5px]',
                item.status === 'running' ? 'bg-white font-semibold text-[#262B7A]' : 'text-[#1B1F27]',
              )}
            >
              <div className="flex min-w-0 items-center gap-2">
                {item.status === 'running' ? (
                  <CircleNotch
                    size={14}
                    weight="bold"
                    className="shrink-0 animate-spin text-[#7B80EA]"
                  />
                ) : (
                  <Circle size={13} weight="bold" className="shrink-0 text-[#CDD3DD]" />
                )}
                <span className="truncate">{item.title}</span>
              </div>
              {item.meta && (
                <span className="shrink-0 font-glaze-mono text-[11px] text-[#8A90A0]">
                  {item.meta}
                </span>
              )}
            </div>
          ))}
        </div>
      )}

      {showCompleted && completed.length > 0 && (
        <div className="flex flex-col gap-1">
          <span className="px-1 text-[10.5px] font-bold tracking-[0.04em] text-[#8A90A0] uppercase">
            已完成 ({completed.length})
          </span>
          {completed.map((item) => (
            <div
              key={item.id}
              className="flex items-center justify-between gap-2 rounded-[10px] px-2.5 py-1 text-[12px] text-[#6B7280]"
            >
              <div className="flex min-w-0 items-center gap-2">
                <CheckCircle
                  size={14}
                  weight="fill"
                  className="shrink-0"
                  style={{ color: SEMANTIC_TOKENS.normal.dot }}
                />
                <span className="truncate line-through decoration-[#CDD3DD]">{item.title}</span>
              </div>
              {item.meta && (
                <span className="shrink-0 font-glaze-mono text-[10.5px] text-[#8A90A0]">
                  {item.meta}
                </span>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

ai-context-meter.sourceCode:
import * as React from 'react'
import { Popover as BasePopover } from '@base-ui/react/popover'
import { CaretDown, Check, Cpu, Lightning, Sparkle } from '@phosphor-icons/react'
import { cn } from 'cn'
import { SegmentedProgress } from '@/components/ui/progress'
import { HUE_PALETTES, SEMANTIC_TOKENS, type Hue } from '@/lib/tokens'
import { POPUP_SURFACE, POPUP_TRANSITION_CLASS, PopupTriggerScope } from '@/lib/motion'

export interface AiContextUsage {
  usedTokens: number
  maxTokens: number
  inputTokens?: number
  outputTokens?: number
  cachedTokens?: number
  reasoningTokens?: number
  estimatedCost?: string
}

function formatCompactTokens(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}k`
  return String(n)
}

export interface AiContextMeterProps {
  usage: AiContextUsage
  /** Trigger button style */
  surface?: 'soft' | 'white'
  className?: string
}

export function AiContextMeter({
  usage,
  surface = 'soft',
  className,
}: AiContextMeterProps) {
  const pct = Math.min(100, Math.round((usage.usedTokens / Math.max(1, usage.maxTokens)) * 100))
  const ringColor =
    pct >= 85
      ? SEMANTIC_TOKENS.error.dot
      : pct >= 65
        ? SEMANTIC_TOKENS.warning.dot
        : HUE_PALETTES.periwinkle[500]

  const r = 7
  const c = 2 * Math.PI * r
  const offset = c * (1 - pct / 100)

  const segments = [
    ...(usage.inputTokens
      ? [{ label: '输入', value: usage.inputTokens, color: HUE_PALETTES.sky[500] }]
      : []),
    ...(usage.cachedTokens
      ? [{ label: '缓存命中', value: usage.cachedTokens, color: HUE_PALETTES.mint[500] }]
      : []),
    ...(usage.reasoningTokens
      ? [{ label: '推理', value: usage.reasoningTokens, color: HUE_PALETTES.lilac[500] }]
      : []),
    ...(usage.outputTokens
      ? [{ label: '输出', value: usage.outputTokens, color: HUE_PALETTES.periwinkle[500] }]
      : []),
  ]

  return (
    <BasePopover.Root>
      <PopupTriggerScope>
        <BasePopover.Trigger
          className={cn(
            'inline-flex h-8 cursor-pointer items-center gap-1.5 rounded-full px-3 text-[12px] font-semibold text-[#1B1F27] outline-none transition-colors',
            surface === 'white' ? 'bg-white hover:bg-[#FAFBFD]' : 'bg-[#F2F3F5] hover:bg-[#E8EBF0]',
            className,
          )}
        >
          <svg width="18" height="18" viewBox="0 0 18 18" className="-rotate-90">
            <circle cx="9" cy="9" r={r} fill="none" stroke="#E8EBF0" strokeWidth="2.5" />
            <circle
              cx="9"
              cy="9"
              r={r}
              fill="none"
              stroke={ringColor}
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeDasharray={c}
              strokeDashoffset={offset}
            />
          </svg>
          <span className="font-glaze-mono tabular-nums">{pct}%</span>
        </BasePopover.Trigger>
      </PopupTriggerScope>

      <BasePopover.Portal>
        <BasePopover.Positioner side="top" align="end" sideOffset={8} className="z-50">
          <BasePopover.Popup
            className={cn(POPUP_SURFACE, POPUP_TRANSITION_CLASS, 'w-72 p-4')}
          >
            <div className="flex items-center justify-between gap-2">
              <span className="font-glaze-display text-[14px] font-extrabold text-[#1B1F27]">
                上下文窗口用量
              </span>
              <span className="font-glaze-mono text-[12px] font-bold" style={{ color: ringColor }}>
                {pct}%
              </span>
            </div>
            <div className="mt-1 flex items-baseline justify-between text-[12px] text-[#6B7280]">
              <span>
                {formatCompactTokens(usage.usedTokens)} / {formatCompactTokens(usage.maxTokens)} tokens
              </span>
              {usage.estimatedCost && (
                <span className="font-glaze-mono font-semibold text-[#1B1F27]">
                  {usage.estimatedCost}
                </span>
              )}
            </div>

            {segments.length > 0 && (
              <div className="mt-3">
                <SegmentedProgress segments={segments} />
              </div>
            )}

            <div className="mt-3 flex flex-col gap-1.5 border-t border-[#EEF0F3] pt-2.5 text-[12px]">
              {usage.inputTokens !== undefined && (
                <div className="flex items-center justify-between">
                  <span className="text-[#6B7280]">输入 Tokens</span>
                  <span className="font-glaze-mono font-semibold text-[#1B1F27]">
                    {usage.inputTokens.toLocaleString()}
                  </span>
                </div>
              )}
              {usage.cachedTokens !== undefined && (
                <div className="flex items-center justify-between">
                  <span className="text-[#6B7280]">Prompt 缓存命中</span>
                  <span className="font-glaze-mono font-semibold text-[#2F6B28]">
                    {usage.cachedTokens.toLocaleString()}
                  </span>
                </div>
              )}
              {usage.reasoningTokens !== undefined && (
                <div className="flex items-center justify-between">
                  <span className="text-[#6B7280]">深度推理 Tokens</span>
                  <span className="font-glaze-mono font-semibold text-[#6A2D70]">
                    {usage.reasoningTokens.toLocaleString()}
                  </span>
                </div>
              )}
              {usage.outputTokens !== undefined && (
                <div className="flex items-center justify-between">
                  <span className="text-[#6B7280]">输出 Tokens</span>
                  <span className="font-glaze-mono font-semibold text-[#1B1F27]">
                    {usage.outputTokens.toLocaleString()}
                  </span>
                </div>
              )}
            </div>
          </BasePopover.Popup>
        </BasePopover.Positioner>
      </BasePopover.Portal>
    </BasePopover.Root>
  )
}

export interface AiModelOption {
  id: string
  name: string
  provider: string
  contextWindow?: string
  tag?: string
  hue?: Hue
  description?: string
}

export interface AiModelSelectorProps {
  models: AiModelOption[]
  value: string
  onValueChange: (modelId: string) => void
  surface?: 'soft' | 'white'
  side?: 'top' | 'bottom'
  className?: string
}

export function AiModelSelector({
  models,
  value,
  onValueChange,
  surface = 'soft',
  side = 'top',
  className,
}: AiModelSelectorProps) {
  const [open, setOpen] = React.useState(false)
  const current = models.find((m) => m.id === value) ?? models[0]
  const activePalette = HUE_PALETTES[current?.hue ?? 'periwinkle']

  return (
    <BasePopover.Root open={open} onOpenChange={setOpen}>
      <PopupTriggerScope>
        <BasePopover.Trigger
          className={cn(
            'inline-flex h-8 cursor-pointer items-center gap-1.5 rounded-full px-3 text-[12px] font-semibold text-[#1B1F27] outline-none transition-colors data-popup-open:ring-2 data-popup-open:ring-[#7B80EA]',
            surface === 'white' ? 'bg-white hover:bg-[#FAFBFD]' : 'bg-[#F2F3F5] hover:bg-[#E8EBF0]',
            className,
          )}
        >
          <span
            className="inline-flex h-4 w-4 items-center justify-center rounded-full"
            style={{ backgroundColor: activePalette[100], color: activePalette[700] }}
          >
            <Sparkle size={10} weight="fill" />
          </span>
          <span className="max-w-[140px] truncate">{current?.name}</span>
          <CaretDown size={12} weight="bold" className="text-[#8A90A0]" />
        </BasePopover.Trigger>
      </PopupTriggerScope>

      <BasePopover.Portal>
        <BasePopover.Positioner side={side} align="start" sideOffset={8} className="z-50">
          <BasePopover.Popup
            className={cn(POPUP_SURFACE, POPUP_TRANSITION_CLASS, 'w-80 p-2')}
          >
            <div className="px-2.5 pt-1 pb-1.5 text-[11px] font-bold tracking-[0.04em] text-[#8A90A0] uppercase">
              选择推理模型
            </div>
            <div className="flex flex-col gap-1">
              {models.map((m) => {
                const selected = m.id === value
                const palette = HUE_PALETTES[m.hue ?? 'periwinkle']
                return (
                  <button
                    key={m.id}
                    type="button"
                    onClick={() => {
                      onValueChange(m.id)
                      setOpen(false)
                    }}
                    className={cn(
                      'flex w-full cursor-pointer items-start justify-between gap-2.5 rounded-[12px] px-2.5 py-2 text-left transition-colors outline-none',
                      selected ? 'bg-[#F3F4FE]' : 'hover:bg-[#F6F7F9]',
                    )}
                  >
                    <div className="flex min-w-0 items-start gap-2.5">
                      <span
                        className="mt-0.5 inline-flex h-7 w-7 shrink-0 items-center justify-center rounded-[9px]"
                        style={{ backgroundColor: palette[100], color: palette[700] }}
                      >
                        {m.tag === '极速' ? (
                          <Lightning size={14} weight="fill" />
                        ) : (
                          <Cpu size={14} weight="duotone" />
                        )}
                      </span>
                      <div className="min-w-0">
                        <div className="flex items-center gap-1.5">
                          <span className="truncate text-[13px] font-bold text-[#1B1F27]">
                            {m.name}
                          </span>
                          {m.tag && (
                            <span
                              className="rounded-full px-1.5 py-0.5 text-[10px] font-bold"
                              style={{ backgroundColor: palette[100], color: palette[700] }}
                            >
                              {m.tag}
                            </span>
                          )}
                        </div>
                        <div className="mt-0.5 flex items-center gap-1.5 text-[11px] text-[#6B7280]">
                          <span>{m.provider}</span>
                          {m.contextWindow && <span>· {m.contextWindow}</span>}
                        </div>
                        {m.description && (
                          <div className="mt-0.5 line-clamp-1 text-[11px] text-[#8A90A0]">
                            {m.description}
                          </div>
                        )}
                      </div>
                    </div>
                    {selected && (
                      <Check size={15} weight="bold" className="mt-1 shrink-0 text-[#4A4FB8]" />
                    )}
                  </button>
                )
              })}
            </div>
          </BasePopover.Popup>
        </BasePopover.Positioner>
      </BasePopover.Portal>
    </BasePopover.Root>
  )
}

ai-artifact.sourceCode:
import * as React from 'react'
import {
  ArrowCounterClockwise,
  CaretRight,
  Check,
  Copy,
  FileCode,
  FlagBanner,
  Folder,
  FolderOpen,
} from '@phosphor-icons/react'
import { cn } from 'cn'
import { SegmentedControl } from '@/components/ui/segmented-control'
import { HUE_PALETTES, SEMANTIC_TOKENS, type Hue } from '@/lib/tokens'
import { PRESS_CLASS } from '@/lib/motion'

export interface AiArtifactProps extends React.HTMLAttributes<HTMLDivElement> {
  title: string
  subtitle?: string
  badge?: string
  hue?: Hue
  /** Dual-mode view: interactive preview and raw source code */
  preview?: React.ReactNode
  code?: React.ReactNode
  copyText?: string
  defaultView?: 'preview' | 'code'
  extraActions?: React.ReactNode
}

export function AiArtifact({
  title,
  subtitle,
  badge,
  hue = 'periwinkle',
  preview,
  code,
  copyText,
  defaultView = 'preview',
  extraActions,
  className,
  children,
  ...props
}: AiArtifactProps) {
  const [view, setView] = React.useState<'preview' | 'code'>(
    preview ? defaultView : 'code',
  )
  const [copied, setCopied] = React.useState(false)
  const palette = HUE_PALETTES[hue]
  const hasToggle = Boolean(preview && code)

  const handleCopy = () => {
    if (copyText) navigator.clipboard?.writeText(copyText).catch(() => {})
    setCopied(true)
    window.setTimeout(() => setCopied(false), 1600)
  }

  return (
    <div
      className={cn('flex w-full flex-col overflow-hidden rounded-tile bg-white', className)}
      {...props}
    >
      <div className="flex flex-wrap items-center justify-between gap-2 border-b border-[#EEF0F3] px-4 py-3">
        <div className="flex min-w-0 items-center gap-2.5">
          <span
            className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-[10px]"
            style={{ backgroundColor: palette[100], color: palette[700] }}
          >
            <FileCode size={16} weight="duotone" />
          </span>
          <div className="min-w-0">
            <div className="flex items-center gap-2">
              <span className="truncate font-glaze-display text-[14px] font-extrabold text-[#1B1F27]">
                {title}
              </span>
              {badge && (
                <span
                  className="shrink-0 rounded-full px-2 py-0.5 font-glaze-mono text-[10.5px] font-bold"
                  style={{ backgroundColor: palette[50], color: palette[700] }}
                >
                  {badge}
                </span>
              )}
            </div>
            {subtitle && <div className="truncate text-[11.5px] text-[#6B7280]">{subtitle}</div>}
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-1.5">
          {hasToggle && (
            <SegmentedControl
              size="sm"
              value={view}
              onValueChange={setView}
              options={[
                { value: 'preview', label: '预览' },
                { value: 'code', label: '源码' },
              ]}
            />
          )}
          {copyText && (
            <button
              type="button"
              onClick={handleCopy}
              className={cn(
                'inline-flex h-8 cursor-pointer items-center gap-1 rounded-full bg-[#F2F3F5] px-3 text-[12px] font-semibold text-[#1B1F27] hover:bg-[#E8EBF0]',
                PRESS_CLASS,
              )}
            >
              {copied ? <Check size={13} weight="bold" /> : <Copy size={13} />}
              <span>{copied ? '已复制' : '复制'}</span>
            </button>
          )}
          {extraActions}
        </div>
      </div>

      <div className="min-h-0 flex-1 p-4">
        {hasToggle ? (view === 'preview' ? preview : code) : (preview ?? code ?? children)}
      </div>
    </div>
  )
}

export interface AiFileTreeNode {
  path: string
  name: string
  type: 'file' | 'folder'
  status?: 'added' | 'modified' | 'deleted'
  children?: AiFileTreeNode[]
}

export interface AiFileTreeProps extends React.HTMLAttributes<HTMLDivElement> {
  nodes: AiFileTreeNode[]
  selectedPath?: string
  onSelectPath?: (path: string) => void
  defaultExpanded?: string[]
}

export function AiFileTree({
  nodes,
  selectedPath,
  onSelectPath,
  defaultExpanded = [],
  className,
  ...props
}: AiFileTreeProps) {
  const [expanded, setExpanded] = React.useState<Set<string>>(() => new Set(defaultExpanded))

  const toggle = (p: string) => {
    setExpanded((prev) => {
      const next = new Set(prev)
      if (next.has(p)) next.delete(p)
      else next.add(p)
      return next
    })
  }

  const renderNode = (node: AiFileTreeNode, depth: number) => {
    const isFolder = node.type === 'folder'
    const isOpen = expanded.has(node.path)
    const isSelected = selectedPath === node.path
    const statusBadge =
      node.status === 'added'
        ? { label: 'A', color: SEMANTIC_TOKENS.normal.ink, bg: SEMANTIC_TOKENS.normal.pillBg }
        : node.status === 'modified'
          ? { label: 'M', color: SEMANTIC_TOKENS.warning.ink, bg: SEMANTIC_TOKENS.warning.pillBg }
          : node.status === 'deleted'
            ? { label: 'D', color: SEMANTIC_TOKENS.error.ink, bg: SEMANTIC_TOKENS.error.pillBg }
            : null

    return (
      <div key={node.path}>
        <button
          type="button"
          onClick={() => (isFolder ? toggle(node.path) : onSelectPath?.(node.path))}
          style={{ paddingLeft: 10 + depth * 14 }}
          className={cn(
            'flex w-full cursor-pointer items-center justify-between gap-2 rounded-[10px] py-1.5 pr-2.5 text-left text-[12.5px] transition-colors outline-none',
            isSelected
              ? 'bg-[#E4E6FD] font-bold text-[#262B7A]'
              : 'font-medium text-[#1B1F27] hover:bg-white',
          )}
        >
          <span className="flex min-w-0 items-center gap-1.5">
            {isFolder ? (
              <>
                <CaretRight
                  size={11}
                  weight="bold"
                  className={cn(
                    'shrink-0 text-[#8A90A0] transition-transform duration-150',
                    isOpen && 'rotate-90',
                  )}
                />
                {isOpen ? (
                  <FolderOpen size={14} weight="duotone" className="shrink-0 text-[#4A9BD8]" />
                ) : (
                  <Folder size={14} weight="duotone" className="shrink-0 text-[#4A9BD8]" />
                )}
              </>
            ) : (
              <>
                <span className="w-[11px] shrink-0" />
                <FileCode size={14} weight="duotone" className="shrink-0 text-[#7B80EA]" />
              </>
            )}
            <span className="truncate font-glaze-mono">{node.name}</span>
          </span>
          {statusBadge && (
            <span
              className="shrink-0 rounded-full px-1.5 py-0.5 font-glaze-mono text-[10px] font-bold"
              style={{ backgroundColor: statusBadge.bg, color: statusBadge.color }}
            >
              {statusBadge.label}
            </span>
          )}
        </button>
        {isFolder && isOpen && node.children?.map((child) => renderNode(child, depth + 1))}
      </div>
    )
  }

  return (
    <div
      className={cn('flex w-full flex-col gap-0.5 rounded-inner bg-[#F6F7F9] p-2', className)}
      {...props}
    >
      {nodes.map((n) => renderNode(n, 0))}
    </div>
  )
}

export interface AiCheckpointProps extends React.HTMLAttributes<HTMLDivElement> {
  label?: string
  timestamp?: string
  onRestore?: () => void
  restoreLabel?: string
}

export function AiCheckpoint({
  label = '检查点已保存',
  timestamp,
  onRestore,
  restoreLabel = '回溯到此节点',
  className,
  ...props
}: AiCheckpointProps) {
  return (
    <div className={cn('flex w-full items-center gap-3 py-1', className)} {...props}>
      <span className="h-px flex-1 bg-[#E8EBF0]" />
      <div className="flex items-center gap-2 rounded-full bg-[#F6F7F9] py-1 pr-2 pl-3 text-[11.5px] font-semibold text-[#5B6170]">
        <FlagBanner size={13} weight="duotone" className="text-[#4A4FB8]" />
        <span>{label}</span>
        {timestamp && <span className="font-glaze-mono text-[10.5px] text-[#8A90A0]">{timestamp}</span>}
        {onRestore && (
          <button
            type="button"
            onClick={onRestore}
            className={cn(
              'ml-1 inline-flex cursor-pointer items-center gap-1 rounded-full bg-white px-2.5 py-0.5 text-[11px] font-bold text-[#123A5C] hover:bg-[#E4E6FD] hover:text-[#262B7A]',
              PRESS_CLASS,
            )}
          >
            <ArrowCounterClockwise size={11} weight="bold" />
            <span>{restoreLabel}</span>
          </button>
        )}
      </div>
      <span className="h-px flex-1 bg-[#E8EBF0]" />
    </div>
  )
}

topology-canvas.sourceCode:
import * as React from 'react'
import {
  Background,
  BackgroundVariant,
  ReactFlow,
  ReactFlowProvider,
  useNodesState,
  useReactFlow,
  type FitViewOptions,
  type NodeMouseHandler,
  type EdgeMouseHandler,
  type ReactFlowProps,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import { cn } from 'cn'
import { TopologyEdge } from '@/components/ui/topology-edge'
import { TopologyGroup } from '@/components/ui/topology-group'
import { TopologyNode } from '@/components/ui/topology-node'
import type { Status } from '@/lib/tokens'
import {
  TopologyViewContext,
  isTopologyGroupNode,
  traceTopologyPath,
  useTopologyLayout,
  useTopologyView,
  type TopologyDirection,
  type TopologyFlowEdge,
  type TopologyFlowNode,
  type TopologyLayoutOptions,
  type TopologySelection,
} from '@/lib/topology'

const GLAZE_NODE_TYPES = {
  topologyNode: TopologyNode,
  topologyGroup: TopologyGroup,
} as const

const GLAZE_EDGE_TYPES = {
  topologyEdge: TopologyEdge,
} as const

const DEFAULT_FIT_VIEW_OPTIONS: FitViewOptions = {
  padding: 0.14,
  duration: 280,
}

export interface TopologyCanvasProps
  extends Omit<
    ReactFlowProps<TopologyFlowNode, TopologyFlowEdge>,
    'nodes' | 'edges' | 'nodeTypes' | 'edgeTypes' | 'onNodeClick' | 'onEdgeClick' | 'onSelectionChange'
  > {
  /** Topology nodes (including optional `topologyGroup` parent containers) */
  nodes: TopologyFlowNode[]
  /** Topology links connecting nodes */
  edges: TopologyFlowEdge[]
  /** Active layout direction controlling port handle placement */
  direction?: TopologyDirection
  /** Toggle animated directional traffic flow on edges */
  animateFlow?: boolean
  /** Default visual density for device/service nodes */
  density?: 'compact' | 'detailed'
  /** Controlled selection (node or edge) */
  selection?: TopologySelection | null
  /** Callback fired when selection changes */
  onSelectionChange?: (selection: TopologySelection | null) => void
  /** Automatically trace and highlight upstream/downstream paths on selection */
  traceOnSelect?: boolean
  /** Direction of path tracing when an item is selected */
  traceDirection?: 'both' | 'upstream' | 'downstream'
  /** Optional search keyword dimming non-matching nodes */
  searchQuery?: string
  /** Optional status filter ('all' | Status) dimming non-matching nodes */
  statusFilter?: 'all' | Status
  /** External status overrides for nodes (e.g. fault impact simulation) */
  nodeStatusOverrides?: Map<string, Status>
  /** External status overrides for edges */
  edgeStatusOverrides?: Map<string, Status>
  /** Show subtle Glaze dot grid background */
  showGrid?: boolean
  /** Canvas surface mode ('canvas' uses #F2F4F8, 'transparent' blends inside a Tile) */
  surface?: 'canvas' | 'transparent'
  /** Allow dragging nodes to adjust layout temporarily */
  draggable?: boolean
  /** Automatically compute collision-free compound layout with Eclipse Layout Kernel (`elkjs`) */
  autoLayout?: boolean
  /** Fine-grained ELK layout spacing & algorithm options when `autoLayout` is enabled */
  layoutOptions?: Omit<TopologyLayoutOptions, 'direction' | 'density'>
  /** Automatically re-fit viewport when `fitViewKey` changes */
  fitViewKey?: string | number
  /** Container className (must supply explicit height or flex-1) */
  className?: string
  /** Floating overlay children (`TopologyToolbar`, `TopologyLegend`, `TopologyMinimap`, etc.) */
  children?: React.ReactNode
}

function TopologyCanvasInner({
  nodes,
  edges,
  direction = 'LR',
  animateFlow = true,
  density = 'detailed',
  selection: controlledSelection,
  onSelectionChange,
  traceOnSelect = true,
  traceDirection = 'both',
  searchQuery = '',
  statusFilter = 'all',
  nodeStatusOverrides,
  edgeStatusOverrides,
  showGrid = true,
  surface = 'canvas',
  draggable = false,
  autoLayout = true,
  layoutOptions,
  fitViewKey,
  className,
  children,
  ...rest
}: TopologyCanvasProps) {
  const { fitView } = useReactFlow()
  const {
    nodes: resolvedNodes,
    isLayouting,
    layoutVersion,
  } = useTopologyLayout(nodes, edges, {
    enabled: autoLayout,
    direction,
    density,
    ...layoutOptions,
  })
  const [interactiveNodes, setInteractiveNodes, handleNodesChange] =
    useNodesState<TopologyFlowNode>(resolvedNodes)
  React.useEffect(() => {
    setInteractiveNodes(resolvedNodes)
  }, [resolvedNodes, setInteractiveNodes])

  const [uncontrolledSelection, setUncontrolledSelection] =
    React.useState<TopologySelection | null>(null)

  const selection =
    controlledSelection !== undefined ? controlledSelection : uncontrolledSelection

  // Guard against mobile WebKit/Chrome delayed ghost-clicks landing on a node
  // directly behind a floating TopologyInspector right after it unmounts.
  const prevSelectionRef = React.useRef<TopologySelection | null>(selection)
  const lastDismissedAtRef = React.useRef(0)
  React.useEffect(() => {
    if (prevSelectionRef.current !== null && selection === null) {
      lastDismissedAtRef.current = performance.now()
    }
    prevSelectionRef.current = selection
  }, [selection])

  const selectItem = React.useCallback(
    (next: TopologySelection | null) => {
      if (next === null && selection !== null) {
        lastDismissedAtRef.current = performance.now()
      }
      if (controlledSelection === undefined) {
        setUncontrolledSelection(next)
      }
      onSelectionChange?.(next)
    },
    [controlledSelection, onSelectionChange, selection],
  )

  const effectiveNodeOverrides = React.useMemo(
    () => nodeStatusOverrides ?? new Map<string, Status>(),
    [nodeStatusOverrides],
  )
  const effectiveEdgeOverrides = React.useMemo(
    () => edgeStatusOverrides ?? new Map<string, Status>(),
    [edgeStatusOverrides],
  )

  // Compute highlighted node & edge sets from selection trace + search + status filter
  const { hasActiveHighlight, highlightedNodeIds, highlightedEdgeIds } = React.useMemo(() => {
    const trimmed = searchQuery.trim().toLowerCase()
    const hasFilter = trimmed.length > 0 || statusFilter !== 'all'

    if (selection && traceOnSelect) {
      const traced = traceTopologyPath(nodes, edges, selection, traceDirection)
      return {
        hasActiveHighlight: traced.nodeIds.size > 0 || traced.edgeIds.size > 0,
        highlightedNodeIds: traced.nodeIds,
        highlightedEdgeIds: traced.edgeIds,
      }
    }

    if (hasFilter) {
      const matchedNodes = new Set<string>()
      const matchedEdges = new Set<string>()

      for (const n of nodes) {
        if (isTopologyGroupNode(n)) continue
        const st = effectiveNodeOverrides.get(n.id) ?? n.data.status ?? 'normal'
        const statusOk = statusFilter === 'all' || st === statusFilter
        const text = `${n.data.label} ${n.data.subtitle ?? ''} ${n.data.address ?? ''} ${n.data.badge ?? ''} ${n.data.layer ?? ''}`.toLowerCase()
        const queryOk = !trimmed || text.includes(trimmed)

        if (statusOk && queryOk) {
          matchedNodes.add(n.id)
          if (n.parentId) matchedNodes.add(n.parentId)
        }
      }

      for (const e of edges) {
        if (matchedNodes.has(e.source) && matchedNodes.has(e.target)) {
          matchedEdges.add(e.id)
        }
      }

      return {
        hasActiveHighlight: true,
        highlightedNodeIds: matchedNodes,
        highlightedEdgeIds: matchedEdges,
      }
    }

    return {
      hasActiveHighlight: false,
      highlightedNodeIds: new Set<string>(),
      highlightedEdgeIds: new Set<string>(),
    }
  }, [
    nodes,
    edges,
    selection,
    traceOnSelect,
    traceDirection,
    searchQuery,
    statusFilter,
    effectiveNodeOverrides,
  ])

  // Re-fit view smoothly whenever ELK layout finishes or preset/direction changes
  React.useEffect(() => {
    if (autoLayout && isLayouting) return
    const timer = window.setTimeout(() => {
      void fitView(DEFAULT_FIT_VIEW_OPTIONS)
    }, 50)
    return () => window.clearTimeout(timer)
  }, [fitViewKey, direction, layoutVersion, autoLayout, isLayouting, fitView])

  const handleNodeClick: NodeMouseHandler<TopologyFlowNode> = React.useCallback(
    (_event, node) => {
      if (performance.now() - lastDismissedAtRef.current < 360) return
      selectItem(
        selection?.type === 'node' && selection.id === node.id
          ? null
          : { type: 'node', id: node.id },
      )
    },
    [selectItem, selection],
  )

  const handleEdgeClick: EdgeMouseHandler<TopologyFlowEdge> = React.useCallback(
    (_event, edge) => {
      if (performance.now() - lastDismissedAtRef.current < 360) return
      selectItem(
        selection?.type === 'edge' && selection.id === edge.id
          ? null
          : { type: 'edge', id: edge.id },
      )
    },
    [selectItem, selection],
  )

  const handlePaneClick = React.useCallback(() => {
    if (selection) selectItem(null)
  }, [selection, selectItem])

  const ctxValue = React.useMemo(
    () => ({
      direction,
      animateFlow,
      density,
      selection,
      hasActiveHighlight,
      highlightedNodeIds,
      highlightedEdgeIds,
      nodeStatusOverrides: effectiveNodeOverrides,
      edgeStatusOverrides: effectiveEdgeOverrides,
      selectItem,
    }),
    [
      direction,
      animateFlow,
      density,
      selection,
      hasActiveHighlight,
      highlightedNodeIds,
      highlightedEdgeIds,
      effectiveNodeOverrides,
      effectiveEdgeOverrides,
      selectItem,
    ],
  )

  return (
    <TopologyViewContext.Provider value={ctxValue}>
      <div
        data-surface={surface}
        data-direction={direction}
        className={cn(
          'glaze-topology relative h-full w-full overflow-hidden',
          surface === 'canvas' ? 'bg-[#F2F4F8]' : 'bg-transparent',
          className,
        )}
      >
        <ReactFlow<TopologyFlowNode, TopologyFlowEdge>
          nodes={interactiveNodes}
          edges={edges}
          nodeTypes={GLAZE_NODE_TYPES}
          edgeTypes={GLAZE_EDGE_TYPES}
          onNodesChange={draggable ? handleNodesChange : undefined}
          onNodeClick={handleNodeClick}
          onEdgeClick={handleEdgeClick}
          onPaneClick={handlePaneClick}
          nodesDraggable={draggable}
          nodesConnectable={false}
          elementsSelectable
          fitView
          fitViewOptions={DEFAULT_FIT_VIEW_OPTIONS}
          minZoom={0.3}
          maxZoom={1.75}
          proOptions={{ hideAttribution: true }}
          className={cn(
            'transition-opacity duration-150',
            autoLayout && layoutVersion === 0 && isLayouting ? 'opacity-0' : 'opacity-100',
          )}
          {...rest}
        >
          {showGrid && (
            <Background
              variant={BackgroundVariant.Dots}
              gap={22}
              size={1.4}
              color="#CBD2DF"
            />
          )}
          {children}
        </ReactFlow>
      </div>
    </TopologyViewContext.Provider>
  )
}

/**
 * Glaze Topology & Architecture Canvas powered by `@xyflow/react`.
 * Wraps `ReactFlowProvider`, Glaze custom node/group/edge types, path-trace highlighting,
 * search/status filtering, and fault-impact overrides.
 */
export function TopologyCanvas(props: TopologyCanvasProps) {
  return (
    <ReactFlowProvider>
      <TopologyCanvasInner {...props} />
    </ReactFlowProvider>
  )
}

export { useTopologyView as useTopology }

